package indexer

import (
	"strings"
	"unicode/utf8"
)

// IsBinaryContent reports whether content looks like binary data (null bytes or low text ratio).
func IsBinaryContent(content []byte) bool {
	if len(content) == 0 {
		return false
	}
	sample := content
	if len(sample) > 8192 {
		sample = sample[:8192]
	}
	for _, b := range sample {
		if b == 0 {
			return true
		}
	}
	// Reject content that is not valid UTF-8.
	if !utf8.Valid(sample) {
		return true
	}
	return false
}

// IsGeneratedContent detects common "do not edit" / code-generated headers.
func IsGeneratedContent(content string) bool {
	// Only inspect the first ~2KB for markers.
	head := content
	if len(head) > 2048 {
		head = head[:2048]
	}
	lower := strings.ToLower(head)
	markers := []string{
		"code generated",
		"do not edit",
		"autogenerated",
		"auto-generated",
		"@generated",
		"generated by",
		"this file is generated",
	}
	for _, m := range markers {
		if strings.Contains(lower, m) {
			return true
		}
	}
	return false
}

// IsMinifiedOrDense reports likely minified JS/CSS (very long lines, almost no newlines).
func IsMinifiedOrDense(content string) bool {
	if len(content) < 2048 {
		return false
	}
	sample := content
	if len(sample) > 10000 {
		sample = sample[:10000]
	}
	newlines := strings.Count(sample, "\n")
	if newlines == 0 {
		return len(sample) > 500
	}
	avgLineLen := len(sample) / newlines
	return avgLineLen > 400
}
